// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }
    function testFuzz_property(bytes32 guess, address guesser) public {
        vm.assume(guess != bytes32(0));
        vm.assume(guesser != address(0) && guesser != address(this) && guesser != address(c));
        vm.deal(guesser, 1 ether);
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guess);

        vm.roll(block.number + 2);

        uint256 balanceBefore = address(c).balance;
        vm.prank(guesser);
        c.settle();
        uint256 balanceAfter = address(c).balance;

        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - 1)));
        if (guess != answer) {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}
